// Types for the files the site loads, generated by monitor/scripts/export.py from the catalog (monitor/data/interfaces.json,
// schema v2) and the probe store: src/data/monitor.json (one InterfaceRow per interface, the dashboard) and
// src/data/interfaces/<id>.json (one InterfaceEntry, the interface page). The const arrays double as runtime enums for
// assertMonitor() / assertEntry() and as display order where noted.

export const STATUS = ['yes', 'no', 'reported', 'tos_only', 'optional', 'unknown'] as const;
export type Status = (typeof STATUS)[number];

/** Rating by number of restrictions, most restricted first (default sort): D > 20, C 6-20, B 1-5, A none, n/a unknown. */
export const LEVELS = ['D', 'C', 'B', 'A', 'n/a'] as const;
export type Level = (typeof LEVELS)[number];

export const LAYERS = ['edge', 'frontend', 'api', 'contract'] as const;
export type Layer = (typeof LAYERS)[number];

export const FAIL_MODES = ['open', 'closed', 'unknown', 'n/a'] as const;
export type FailMode = (typeof FAIL_MODES)[number];

export const VPN_STATUS = ['no', 'tos_only', 'detect', 'block', 'optional', 'unknown'] as const;
export type VpnStatus = (typeof VPN_STATUS)[number];

export const REPO_STATES = ['open', 'open_stale', 'closed', 'private_now', 'archived', 'none_found'] as const;
export type RepoState = (typeof REPO_STATES)[number];

export const TOS_US = ['yes', 'no', 'partial', 'unknown'] as const;
export type TosUs = (typeof TOS_US)[number];

export const CONFIDENCE = ['high', 'medium', 'low'] as const;
export type Confidence = (typeof CONFIDENCE)[number];

export const CATEGORY_GROUPS = [
  'dex',
  'aggregator',
  'perps',
  'lending',
  'staking',
  'yield',
  'rwa',
  'stablecoin',
  'bridge',
  'prediction',
  'wallet',
  'other'
] as const;
export type CategoryGroup = (typeof CATEGORY_GROUPS)[number];

export const CHAIN_TAGS = ['evm', 'solana', 'bitcoin', 'sui', 'starknet', 'cosmos', 'hyperliquid', 'other'] as const;
export type ChainTag = (typeof CHAIN_TAGS)[number];

/** ISO 3166-1 alpha-2 code ('US') or a sub-national region token 'CC-Name' ('UA-Crimea'). */
export type CountryToken = string;

export interface GeoSite {
  s: Status;
  countries: CountryToken[];
  close_only: CountryToken[];
  method: string;
}

export interface GeoFeature {
  s: Status;
  countries: CountryToken[];
  scope: string;
}

export interface Vpn {
  s: VpnStatus;
  note: string;
}

export interface ScreeningRow {
  s: Status;
  provider: string;
  layer: Layer | null;
}

export interface Screening extends ScreeningRow {
  fail: FailMode | null;
  fail_note: string;
}

/** Identity gate (KYC / accreditation / wallet allowlist). Optional: only present where it was researched. */
export interface KycRow {
  s: Status;
}

export interface Kyc extends KycRow {
  layer: Layer | null;
  scope: string;
}

export interface TosRow {
  us: TosUs;
  us_scope: string;
  restricted: string;
  restricted_codes: CountryToken[];
}

export interface Tos extends TosRow {
  url: string | null;
  updated: string;
}

export interface Alternative {
  name: string;
  url: string;
}

/** A protocol API asked from every probed country (api_probes in monitor/data/interfaces.json; rules stay in the data). */
export interface ApiProbe {
  name: string;
  method: 'GET' | 'POST';
  url: string;
  note: string;
}

export const OBS_STATES = ['ok', 'blocked', 'close_only', 'feature_limited', 'challenge', 'error', 'unknown'] as const;
export type ObservationState = (typeof OBS_STATES)[number];

export const OBS_KINDS = ['site', 'geo_endpoint', 'api'] as const;
export type ObservationKind = (typeof OBS_KINDS)[number];

export const PROXY_TYPES = ['residential', 'isp', 'mobile', 'datacenter', 'tor', 'direct'] as const;
export type ProxyType = (typeof PROXY_TYPES)[number];

/** The one latest verified probe observation a country verdict relies on (monitor.json, `observed`): chosen by export.py
 * the way countryVerdict() would (most trusted vantage, newest; a restriction first, then the protocol's API saying "no
 * restriction", then a served landing page). Region-level observations are only on the interface page. */
export interface ObservedCountry {
  country: string;
  proxy_type: ProxyType;
  at: string;
  kind: ObservationKind;
  url: string;
  http_status: number | null;
  ui_state: ObservationState;
  note: string;
}

/** Latest verified live observation from the P3 probe (monitor/scripts/probe.py), one per country/proxy/kind/url. */
export interface Observation extends ObservedCountry {
  region: CountryToken | null;
  final_url: string;
  flags: Record<string, string | number | boolean>;
}

/** current: the version the protocol points users to; legacy: an older official interface still served but being phased out
 * (listed at the bottom). Defunct interfaces are kept in monitor/data only and never reach the site. */
export const LIFECYCLES = ['current', 'legacy'] as const;
export type Lifecycle = (typeof LIFECYCLES)[number];

/** One interface on the dashboard (monitor.json): what the monitor table, its country filter and the summary page show. */
export interface InterfaceRow {
  id: string;
  name: string;
  /** Version label shown after the name, e.g. "V3". */
  version?: string;
  /** Second name shown next to the name: former name (ex-Maker), parent brand (0x) or product (Aave Pro). */
  aka?: string;
  /** Interfaces of one protocol (its versions) share a family id. */
  family?: string;
  lifecycle: Lifecycle;
  /** Why an interface is legacy, with a date or source. */
  lifecycle_note?: string;
  category: string;
  category_group: CategoryGroup;
  /** EVM networks the official app lists (indicative, from app/docs, not probed). */
  networks: string[];
  url: string;
  /** Where the official-app link goes when it differs from url (a cp0x referral link); the link text keeps url. */
  referral_url?: string;
  frontend_repo: string | null;
  repo_state: RepoState;
  geo_site: GeoSite;
  geo_feature: GeoFeature;
  vpn: Vpn;
  screening: ScreeningRow;
  kyc?: KycRow;
  tos: TosRow;
  alternatives: Alternative[];
  level: Level;
  /** Counted technical restrictions behind the rating (computed by build.py). */
  restrictions: Restrictions;
  /** Per country, the probe observation the country verdict relies on (country level only). */
  observed: ObservedCountry[];
}

/** The whole record of one interface (interfaces/<id>.json), loaded when its page opens. */
export interface InterfaceEntry extends InterfaceRow {
  /** One paragraph about what the protocol is (shown on the interface page, used for SEO). */
  description: string;
  /** Simplified Chinese version of the description (optional). */
  description_zh?: string;
  chains: string;
  chain_tags: ChainTag[];
  repo_status: string;
  repo_last_commit: string | null;
  screening: Screening;
  kyc?: Kyc;
  asset_filter: string;
  tos: Tos;
  notes: string;
  live: string[];
  geo_endpoints: string[];
  api_probes: ApiProbe[];
  evidence: string[];
  confidence: Confidence;
  /** Every latest verified probe observation, including regions and the JSON flags of the answer. */
  observations: Observation[];
}

export interface Restrictions {
  count: number;
  countries: number;
  mechanisms: MechanismKind[];
}

export interface DatasetMeta {
  schema_version: 3;
  generated: string;
  sanctioned_test_address: string;
  sanctioned_test_address_note: string;
  live_check_egress: string;
  status_values: string;
  layer_values: string;
  country_tokens: string;
  regions: Record<CountryToken, string>;
  /** Size of the full catalog in monitor/data; the UI dataset may be a filtered subset (see scope). */
  catalog_total: number;
  scope: string;
  /** Display names of defunct interfaces left out of the site. */
  defunct_hidden: string[];
}

/** monitor.json: the dashboard. */
export interface Monitor {
  meta: DatasetMeta;
  interfaces: InterfaceRow[];
}

/** Every interface in full, assembled from the site files at build time for the prerender. */
export interface Dataset {
  meta: DatasetMeta;
  interfaces: InterfaceEntry[];
}

/** Per-country verdict, in severity order (used for sorting and the legend). */
export const COUNTRY_STATUS = ['blocked', 'close_only', 'feature_limited', 'regional', 'tos_only', 'unknown', 'ok'] as const;
export type CountryStatus = (typeof COUNTRY_STATUS)[number];

export const BASES = ['observed', 'confirmed', 'reported', 'tos', 'inferred'] as const;
export type Basis = (typeof BASES)[number];

export interface CountryVerdict {
  status: CountryStatus;
  basis: Basis;
  /** Free text from the dataset explaining the verdict (method, scope or ToS summary). */
  detail: string;
  /** Sub-national region tokens that triggered a `regional` verdict. */
  regions: CountryToken[];
  /** The live observation the verdict relies on or was checked against, if any. */
  observation?: ObservedCountry;
  /** True when the static verdict and the live observation disagree (both are shown). */
  conflict?: boolean;
}

export type MechanismKind = 'geo_site' | 'geo_feature' | 'screening' | 'vpn' | 'kyc';

export interface EvidenceLink {
  label: string;
  href?: string;
}
